/** Evaluate only the authenticated prepared portable source closure in closed VM ports. */
import fs from 'node:fs';
import vm from 'node:vm';
import {stripTypeScriptTypes} from 'node:module';
export function loadPreparedBatchVoice(box){
 const pin=JSON.parse(fs.readFileSync('upstream.lock.json','utf8')).commit;
 if(JSON.parse(fs.readFileSync('.eliza/client-features/.source.json','utf8')).baseCommit!==pin)throw Error('Run the normal client feature producer for the current pin.');
 const files=['packages/core/src/utils/errors.ts','packages/core/src/errors.ts','packages/core/src/utils/reasoning-tags.ts','packages/core/src/spoken-text.ts','packages/core/src/utils/string-boundaries.ts','packages/voice/src/voice-eot.ts','packages/voice/src/respond-gate.ts','packages/ui/src/voice/tts-playback-activity.ts','packages/ui/src/voice/voice-activity.ts','packages/ui/src/voice/end-of-turn.ts','packages/ui/src/voice/speech-segments.ts','packages/ui/src/voice/voice-chat-playback.ts','packages/ui/src/voice/batch-conversation.ts'];
 for(const file of files){let source=stripTypeScriptTypes(fs.readFileSync('.eliza/client-features/'+file,'utf8'),{mode:'transform'});source=source.replace(/^import[\s\S]*?;\n/gm,'').replace(/^export\s*\{[\s\S]*?\}(?:\s*from\s*[^;]+)?;\n/gm,'');const names=[...source.matchAll(/^export\s+(?:async\s+)?(?:function|class|const)\s+(\w+)/gm)].map(match=>match[1]);source=source.replace(/^export\s+/gm,'');vm.runInNewContext('{'+source+'\n'+names.map(name=>'globalThis.'+name+'='+name+';').join('\n')+'}',box,{filename:file});}
}
export function voiceFakeClock(){let now=0,next=0;const timers=new Map();const clock={Date:class extends Date{static now(){return now;}},performance:{now:()=>now},setTimeout(fn,delay){const id=++next;timers.set(id,{fn,at:now+delay});return id;},clearTimeout(id){timers.delete(id);},setInterval(fn,delay){const id=++next;timers.set(id,{fn,at:now+delay,interval:delay});return id;},clearInterval(id){timers.delete(id);},async flush(){for(let count=0;count<30;count++)await Promise.resolve();},async advance(ms){const end=now+ms;for(;;){await clock.flush();const pending=[...timers].filter(([,v])=>v.at<=end).sort((a,b)=>a[1].at-b[1].at||a[0]-b[0])[0];if(!pending)break;const [id,timer]=pending;now=timer.at;if(timer.interval)timer.at+=timer.interval;else timers.delete(id);timer.fn();}now=end;await clock.flush();},pending:()=>timers.size};return clock;}
